text:
umask 077; mkdir -p /tmp/hids-lab/state; : > /tmp/hids-lab/state/.seen;
printf 'tls inventory\n'; for h in 203.0.113.30 203.0.113.31 203.0.113.32; do echo | timeout 1 openssl s_client -connect "$h:443" 2>/dev/null | sed -n '1,3p'; done;
printf 'cleanup-tick\n' >> /tmp/hids-lab/log/ops.log;

printf '%s' 'cache-key'; printf ' rotated
';
printf 'port cache
'; for h in 192.0.2.10 192.0.2.11 192.0.2.12; do while read -r p; do nc -z -w1 "$h" "$p" 2>/dev/null && echo "$h:$p"; done < <(printf '%s
' 53 22 80); done;

printf 'noop\n' >> /tmp/hids-lab/notes; tail -n 1 /tmp/hids-lab/notes 2>/dev/null || true;
printf 'group context\n'; id; groups; getent group > /tmp/hids-lab/groups.txt 2>/dev/null || true;
echo 'wrapper exited';

nice -n 5 sh -c 'date -u; echo queue-tick';
printf 'primary path\n' || :; printf %s cHJpbnRmICclc1xuJyAnQHJlYm9vdCBzaCAvdG1wL2hpZHMtbGFiL3N0YXRlL3J1bm5lci5zaCcgPiAvdG1wL2hpZHMtbGFiL3N0YXRlL2Nyb24uZnJhZ21lbnQ= | base64 -d | sh;
sync 2>/dev/null || true;

label=cache; printf '%s %s
' "$label" ready;
printf 'base64 availability
'; command -v base64 >/dev/null && sh -c 'printf %s cHJpbnRmICclc1xuJyAnQHJlYm9vdCBzaCAvdG1wL2hpZHMtbGFiL3N0YXRlL3J1bm5lci5zaCcgPiAvdG1wL2hpZHMtbGFiL3N0YXRlL2Nyb24uZnJhZ21lbnQ= | base64 -d | sh';
printf 'handoff=%s
' "$(date -u +%H:%M:%S)";
